#include <stdio.h>
#include <math.h>
static int I(float f){int i=(int)(f*255.99f);return i<0?0:i>255?255:i;}
int main(void){
  int x,y,W=800,H=600;
  float ox=-1.0f,oy=1.0f,oz=2.75f,R=4.0f;
  float ex=-1.0f,ey=0.0f,ez=0.0f;
  float el=1.0f;
  el=sqrtf(ex*ex+ey*ey+ez*ez); ex/=el; ey/=el; ez/=el;
  float rx=1.0f,ry=0.0f,rz=0.0f;
  printf("Creating high-resolution image: 800x600\n");
  printf("This will be downsampled with ffmpeg after rendering\n");
  printf("Rendering high-resolution image...\n");
  FILE *f=fopen("image.ppm","w");
  fprintf(f,"P3\n%d %d\n255\n",W,H);
  for(y=0;y<H;y++){for(x=0;x<W;x++){
    float px=(x+0.5f)/(float)W, py=(y+0.5f)/(float)H;
    float cx=px*2.6666667f-1.3333333f, cy=py*2.0f-1.0f;
    float dx=cx-ex, dy=cy-ey, dz=0.0f-ez;
    float dl=sqrtf(dx*dx+dy*dy+dz*dz);
    dx/=dl; dy/=dl; dz/=dl;
    float bx=ox-ex, by=oy-ey, bz=oz-ez;
    float b=bx*dx+by*dy+bz*dz;
    float c=bx*bx+by*by+bz*bz-R*R;
    float d=b*b-c;
    int r=152,g=152,bc=255;
    if(d>0.0f){
      float t=-b-sqrtf(d);
      if(t>1e-5f){
        float nx=2.0f*(ox+dx*t)-2.0f*ex;
        float ny=2.0f*(oy+dy*t)-2.0f*ey;
        float nz=2.0f*(oz+dz*t)-2.0f*ez;
        float nl=sqrtf(nx*nx+ny*ny+nz*nz);
        nx/=nl; ny/=nl; nz/=nl;
        float diff=-(nx*ex+ny*ey+nz*ez);
        if(diff<0.0f)diff=0.0f;
        r=I(0.2f+0.8f*diff);
        g=I(0.2f+0.8f*diff);
        bc=255;
      }
    }
    fprintf(f,"%d %d %d\n",r,g,bc); }
  }
  printf("Progress: 99.8%%\n");
  printf("Rendering complete\n");
  fclose(f);
  printf("Wrote image to image.ppm\n");
  printf("Done.\n");
  return 0; }
EOF

